import { Component, OnInit, ViewChild, ElementRef } from '@angular/core';
import { Router } from '@angular/router';
import { HealthService } from '../../services/health.service';
import { AuthService } from '../../services/auth.service';
import { HealthData } from '../../models/health-data.model';

@Component({
  selector: 'app-upload',
  templateUrl: './upload.component.html',
  styleUrls: ['./upload.component.scss']
})
export class UploadComponent implements OnInit {
  selectedFile: File | null = null;
  previewUrl: string | null = null;
  isUploading = false;
  errorMessage: string = '';

  selectedDate: string = '';
  uploadedDates: string[] = [];
  isLoadingDates = false;
  maxDate: string = '';

  showManualEntry = false;
  manualSteps: number = 0;
  manualCalories: number = 0;
  ocrResult: HealthData | null = null;


  successMessage: string = '';
  showSuccessMessage = false;

  @ViewChild('manualEntryForm', { static: false }) manualEntryForm!: ElementRef;

  constructor(
    private healthService: HealthService,
    private authService: AuthService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.maxDate = new Date().toISOString().split('T')[0]; // Set max date to today
    this.selectedDate = this.maxDate; // Set to today

    // Only proceed if user is already authenticated
    if (this.authService.isAuthenticated()) {
      this.loadUploadedDates();
    } else {
      // If not authenticated, try to ensure valid session
      this.authService.ensureValidSession();
    }
  }


  loadUploadedDates(): void {
    this.isLoadingDates = true;
    this.healthService.getUploadedDates().subscribe({
      next: (dates) => {
        this.uploadedDates = dates;
        this.isLoadingDates = false;
      },
      error: (error) => {
        console.error('Error loading uploaded dates:', error);
        this.isLoadingDates = false;
      }
    });
  }

  isDateAlreadyUploaded(date: string): boolean {
    return this.uploadedDates.includes(date);
  }


  onFileSelected(event: any): void {
    const file = event.target.files[0];
    if (file) {

      const maxSize = 2 * 1024 * 1024; // 2MB in bytes

      if (file.size > maxSize) {
        const fileSizeMB = (file.size / (1024 * 1024)).toFixed(2);
        this.errorMessage = `File size (${fileSizeMB}MB) exceeds the 2MB limit. Please choose a smaller image.`;
        this.selectedFile = null;
        this.previewUrl = null;

        // Clear the file input
        event.target.value = '';
        return;
      }

      this.selectedFile = file;
      this.errorMessage = '';


      const reader = new FileReader();
      reader.onload = (e: any) => {
        this.previewUrl = e.target.result;
      };
      reader.readAsDataURL(file);
    }
  }

  onSubmit(): void {
    if (this.selectedFile) {

      if (!this.authService.isAuthenticated()) {
        this.errorMessage = 'No valid authentication token found. Please ensure you are properly authenticated.';
        return;
      }

      this.isUploading = true;
      this.errorMessage = '';

      this.healthService.uploadImage(this.selectedFile, this.selectedDate).subscribe({
        next: (response: any) => {
          this.isUploading = false;

          // Check if OCR was successful (data saved to database)
          if (response.ocrSuccess !== false) {
            // OCR succeeded - data was saved to database
            this.ocrResult = response;

            // Refresh uploaded dates after successful upload
            this.loadUploadedDates();

            // Show success message
            const steps = response.steps ? Math.round(response.steps).toLocaleString() : '0';
            const calories = response.calories ? Math.round(response.calories).toLocaleString() : '0';
            this.showSuccessMsg(`Your Data extracted successfully! Steps: ${steps}, Calories: ${calories}`);

            setTimeout(() => {
              this.router.navigate(['/dashboard'], { 
                state: { 
                  data: response,
                  isNewUpload: true 
                } 
              });
            }, 2000);
          } else {
            // OCR failed - data not saved, show manual entry form
            this.ocrResult = {
              steps: response.steps,
              calories: response.calories,
              date: response.date,
              userEmail: response.userEmail,
              isManual: false
            };

            this.showManualEntry = true;
            this.manualSteps = response.steps || 0;
            this.manualCalories = response.calories || 0;

            // Auto-scroll to manual form after it appears
            this.scrollToManualForm();
          }
        },
        error: (error) => {
          console.error('Upload error:', error);
          this.isUploading = false;

          if (error.status === 409) {
            this.errorMessage = error.error.message || 'This image has already been uploaded';
          } else if (error.status === 401) {
            this.errorMessage = 'Authentication failed. Please check your login status.';
          } else if (error.status === 0) {
            this.errorMessage = 'Cannot connect to server. Please check if the backend is running.';
          } else {
            this.errorMessage = error.error?.message || 'Failed to upload image. Please try again.';
          }
        }
      });
    }
  }

  isOcrDataEmpty(data: HealthData): boolean {
    // Only check if calories are missing - steps can be null/0
    return (!data.calories || data.calories === 0);
  }

  onManualSubmit(): void {
    // Only require calories, steps can be 0
    if (this.manualCalories > 0) {
      this.isUploading = true;
      this.errorMessage = '';

      this.healthService.uploadImageWithManualData(this.manualSteps, this.manualCalories, this.selectedDate).subscribe({
        next: (data: HealthData) => {
          this.isUploading = false;

          // Refresh uploaded dates after successful upload
          this.loadUploadedDates();

          const steps = data.steps ? Math.round(data.steps).toLocaleString() : '0';
          const calories = data.calories ? Math.round(data.calories).toLocaleString() : '0';
          this.showSuccessMsg(`✅ Manual data saved successfully! Steps: ${steps}, Calories: ${calories}`);

          setTimeout(() => {
            this.router.navigate(['/dashboard'], { 
              state: { 
                data: data,
                isNewUpload: true 
              } 
            });
          }, 2000);
        },
        error: (error) => {
          console.error('Manual upload error:', error);
          this.isUploading = false;

          if (error.status === 400) {
            this.errorMessage = error.error.message || 'No recent upload found. Please upload an image first.';
          } else if (error.status === 401) {
            this.errorMessage = 'Authentication failed. Please check your login status.';
          } else if (error.status === 0) {
            this.errorMessage = 'Cannot connect to server. Please check if the backend is running.';
          } else {
            this.errorMessage = error.error?.message || 'Failed to save manual data. Please try again.';
          }
        }
      });
    } else {
      this.errorMessage = 'Please enter valid calories value. Steps are optional.';
    }
  }

  onRetryOcr(): void {
    this.showManualEntry = false;
    this.manualSteps = 0;
    this.manualCalories = 0;
    this.ocrResult = null;
    this.errorMessage = '';
    this.showSuccessMessage = false;
  }

  showSuccessMsg(message: string): void {
    this.successMessage = message;
    this.showSuccessMessage = true;
    this.errorMessage = '';

    setTimeout(() => {
      this.showSuccessMessage = false;
    }, 3000);
  }

  hideSuccessMsg(): void {
    this.showSuccessMessage = false;
  }


  formatFileSize(bytes: number | null | undefined): string {
    if (!bytes) return '';

    if (bytes < 1024) {
      return bytes + ' B';
    } else if (bytes < 1024 * 1024) {
      return (bytes / 1024).toFixed(1) + ' KB';
    } else {
      return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
    }
  }

  goBack(): void {
    this.router.navigate(['/']);
  }

  // Auto-scroll to manual form when it appears
  private scrollToManualForm(): void {
    // Use setTimeout to ensure the DOM has updated
    setTimeout(() => {
      if (this.manualEntryForm) {
        this.manualEntryForm.nativeElement.scrollIntoView({
          behavior: 'smooth',
          block: 'start',
          inline: 'nearest'
        });

        // Optional: Add a subtle highlight effect
        this.highlightManualForm();
      }
    }, 100); // Small delay to ensure form is rendered
  }

  // Optional: Add highlight effect
  private highlightManualForm(): void {
    if (this.manualEntryForm) {
      const element = this.manualEntryForm.nativeElement;

      // Add highlight class
      element.classList.add('highlight-manual-form');

      // Remove highlight after animation
      setTimeout(() => {
        element.classList.remove('highlight-manual-form');
      }, 2000);
    }
  }
}
<div class="min-h-screen flex flex-col">
  <app-header></app-header>

  <main class="flex-1 px-4 sm:px-6 lg:px-8 py-4 sm:py-6">
    <!-- Header -->
    <div class="flex items-center mb-4 sm:mb-6">
      <button 
        (click)="goBack()"
        class="p-1.5 sm:p-2 rounded-xl hover:bg-dark-cyan/20 transition-colors mr-2 sm:mr-3">
        <svg class="w-5 h-5 sm:w-6 sm:h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7"/>
        </svg>
      </button>
      <h1 class="text-xl sm:text-2xl font-bold text-white">Upload Fitness Data</h1>
    </div>

    <!-- Upload Form -->
    <div class="bg-gradient-to-br from-cyan/95 to-dark-cyan/90 backdrop-blur-sm rounded-2xl shadow-xl border border-cyan/30 p-4 sm:p-6 text-white">
      <form class="space-y-4 sm:space-y-6">
        <!-- Success Message -->
        <div *ngIf="showSuccessMessage" class="bg-green-500/20 border border-green-400/50 text-green-200 px-3 sm:px-4 py-2 sm:py-3 rounded-lg backdrop-blur-sm">
          <div class="flex items-center justify-between">
            <div class="flex items-center">
              <svg class="w-4 h-4 sm:w-5 sm:h-5 text-green-400 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/>
              </svg>
              <span class="font-medium text-sm sm:text-base">Success!</span>
            </div>
            <button 
              (click)="hideSuccessMsg()" 
              class="text-green-400 hover:text-green-300 transition-colors"
            >
              <svg class="w-3 h-3 sm:w-4 sm:h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/>
              </svg>
            </button>
          </div>
          <p class="mt-1 text-sm sm:text-base">{{ successMessage }}</p>
        </div>

        <!-- Error Message -->
        <div *ngIf="errorMessage" class="bg-red-500/20 border border-red-400/50 text-red-200 px-3 sm:px-4 py-2 sm:py-3 rounded-lg backdrop-blur-sm text-sm sm:text-base">
          {{ errorMessage }}
        </div>

        <!-- Date Selection -->
        <div>
          <label class="block text-sm font-semibold text-white mb-2">
            Select Date for Health Data
          </label>
          <div class="relative">
            <input 
              type="date" 
              [(ngModel)]="selectedDate"
              name="selectedDate"
              class="w-full px-3 sm:px-4 py-2.5 sm:py-3 bg-white/20 backdrop-blur-sm border border-white/30 rounded-xl text-white placeholder-white/60 focus:outline-none focus:ring-2 focus:ring-cyan/50 focus:border-transparent text-sm sm:text-base"
              [max]="maxDate"
              required>
            <div *ngIf="isDateAlreadyUploaded(selectedDate)" class="mt-2 text-yellow-300 text-xs sm:text-sm flex items-center">
              <svg class="w-3 h-3 sm:w-4 sm:h-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L3.732 16.5c-.77.833.192 2.5 1.732 2.5z"/>
              </svg>
              Data already exists for this date
            </div>
          </div>
        </div>

        <!-- File Upload -->
        <div>
          <label class="block text-sm font-semibold text-white mb-2">
            Fitness App Screenshot
          </label>
          <div class="border-2 border-dashed border-white/30 rounded-xl p-4 sm:p-6 text-center hover:border-white/60 hover:bg-white/5 transition-all duration-300">
            <input
              type="file"
              id="imageUpload"
              accept="image/*"
              (change)="onFileSelected($event)"
              class="hidden"
            />
            <label for="imageUpload" class="cursor-pointer">
              <div *ngIf="!previewUrl; else previewTemplate" class="space-y-3 sm:space-y-4">
                <div class="w-12 h-12 sm:w-16 sm:h-16 bg-white/20 rounded-2xl flex items-center justify-center mx-auto">
                  <svg class="w-6 h-6 sm:w-8 sm:h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"/>
                  </svg>
                </div>
                <div>
                  <p class="text-base sm:text-lg font-medium text-white">Upload your fitness screenshot</p>
                  <p class="text-xs sm:text-sm text-white/70">PNG, JPG, or JPEG up to 2MB</p>
                </div>
              </div>

              <ng-template #previewTemplate>
                <div class="space-y-3 sm:space-y-4">
                  <img
                    [src]="previewUrl"
                    alt="Preview"
                    class="max-h-36 sm:max-h-48 mx-auto rounded-xl shadow-lg"
                  />
                  <div class="text-center">
                    <p class="text-xs sm:text-sm text-white/70">Tap to change image</p>
                    <p class="text-xs text-white/50">{{ formatFileSize(selectedFile?.size) }}</p>
                  </div>
                </div>
              </ng-template>
            </label>
          </div>
        </div>

        <!-- Submit Button -->
        <button
          type="button"
          (click)="onSubmit()"
          [disabled]="!selectedFile || isUploading"
          class="w-full btn-primary text-sm sm:text-lg py-3 sm:py-4 flex items-center justify-center space-x-2 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          <div *ngIf="isUploading; else uploadText" class="flex items-center space-x-2">
            <svg class="animate-spin w-4 h-4 sm:w-5 sm:h-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
              <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
              <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
            </svg>
            <span>Analyzing...</span>
          </div>

          <ng-template #uploadText>
            <svg class="w-5 h-5 sm:w-6 sm:h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z"/>
            </svg>
            <span>Analyze Screenshot</span>
          </ng-template>
        </button>
      </form>
    </div>

    <!-- Manual Entry Form (shown when OCR fails) -->
    <div 
      #manualEntryForm
      *ngIf="showManualEntry" 
      class="mt-6 sm:mt-8 bg-gradient-to-r from-orange/90 to-red/80 backdrop-blur-sm rounded-2xl shadow-xl border border-orange/30 p-4 sm:p-6 text-white"
    >
      <h3 class="text-base sm:text-lg font-semibold text-white mb-3 sm:mb-4 flex items-center">
        <svg class="w-4 h-4 sm:w-5 sm:h-5 text-orange-300 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L3.732 16.5c-.77.833.192 2.5 1.732 2.5z"/>
        </svg>
        OCR Couldn't Extract Data
      </h3>

      <p class="text-white/80 mb-4 sm:mb-6 text-sm sm:text-base">
        Our OCR couldn't automatically extract the health data from your screenshot. 
        Please manually enter the values below:
      </p>

      <form class="space-y-3 sm:space-y-4">
        <!-- Date Selection for Manual Entry -->
        <div class="mb-3 sm:mb-4">
          <label class="block text-sm font-medium text-white/90 mb-2">Date for Health Data</label>
          <input 
            type="date" 
            [(ngModel)]="selectedDate"
            name="manualDate"
            class="w-full px-3 sm:px-4 py-2.5 sm:py-3 bg-white/20 border border-white/30 rounded-lg text-white placeholder-white/60 focus:outline-none focus:ring-2 focus:ring-orange-400 focus:border-transparent text-sm sm:text-base"
            [max]="maxDate"
            required>
          <div *ngIf="isDateAlreadyUploaded(selectedDate)" class="mt-2 text-yellow-300 text-xs sm:text-sm flex items-center">
            <svg class="w-3 h-3 sm:w-4 sm:h-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L3.732 16.5c-.77.833.192 2.5 1.732 2.5z"/>
            </svg>
            Data already exists for this date
          </div>
        </div>

        <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 sm:gap-4">
          <!-- Steps Input - Make Optional -->
          <div>
            <label class="block text-sm font-medium text-white/90 mb-2">
              Steps <span class="text-white/60">(Optional)</span>
            </label>
            <input
              type="number"
              [(ngModel)]="manualSteps"
              name="manualSteps"
              placeholder="Enter steps count (optional)"
              min="0"
              class="w-full px-3 sm:px-4 py-2.5 sm:py-3 bg-white/20 border border-white/30 rounded-lg text-white placeholder-white/60 focus:outline-none focus:ring-2 focus:ring-orange-400 focus:border-transparent text-sm sm:text-base"
            />
          </div>

          <!-- Calories Input - Make Required -->
          <div>
            <label class="block text-sm font-medium text-white/90 mb-2">
              Calories <span class="text-red-300">*</span>
            </label>
            <input
              type="number"
              [(ngModel)]="manualCalories"
              name="manualCalories"
              placeholder="Enter calories count (required)"
              min="0"
              required
              class="w-full px-3 sm:px-4 py-2.5 sm:py-3 bg-white/20 border border-white/30 rounded-lg text-white placeholder-white/60 focus:outline-none focus:ring-2 focus:ring-orange-400 focus:border-transparent text-sm sm:text-base"
            />
          </div>
        </div>

        <!-- Action Buttons -->
        <div class="flex flex-col sm:flex-row space-y-3 sm:space-y-0 sm:space-x-4">
          <button
            type="button"
            (click)="onManualSubmit()"
            [disabled]="!manualCalories || isUploading"
            class="flex-1 bg-orange-600 hover:bg-orange-700 text-white py-2.5 sm:py-3 px-4 sm:px-6 rounded-lg font-medium transition-colors duration-200 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center space-x-2 text-sm sm:text-base"
          >
            <div *ngIf="isUploading; else manualSubmitText" class="flex items-center space-x-2">
              <svg class="animate-spin w-4 h-4 sm:w-5 sm:h-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
              <span>Uploading...</span>
            </div>

            <ng-template #manualSubmitText>
              <svg class="w-4 h-4 sm:w-5 sm:h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8"/>
              </svg>
              <span>Submit</span>
            </ng-template>
          </button>

          <button
            type="button"
            (click)="onRetryOcr()"
            [disabled]="isUploading"
            class="px-4 sm:px-6 py-2.5 sm:py-3 bg-white/20 hover:bg-white/30 text-white rounded-lg font-medium transition-colors duration-200 disabled:opacity-50 disabled:cursor-not-allowed text-sm sm:text-base"
          >
            Try OCR Again
          </button>
        </div>
      </form>
    </div>

    <!-- Tips -->
    <div class="mt-6 sm:mt-8 bg-gradient-to-r from-dark-grey/90 to-grey/80 backdrop-blur-sm rounded-2xl shadow-xl border border-grey/30 p-4 sm:p-6 text-white">
      <h3 class="text-base sm:text-lg font-semibold text-white mb-3 sm:mb-4 flex items-center">
        <svg class="w-4 h-4 sm:w-5 sm:h-5 text-cyan mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/>
        </svg>
        Tips for Best Results
      </h3>
      <div class="space-y-2 sm:space-y-3">
        <div class="flex items-start space-x-2 sm:space-x-3">
          <div class="w-5 h-5 sm:w-6 sm:h-6 bg-cyan/30 rounded-full flex items-center justify-center flex-shrink-0 mt-0.5">
            <span class="text-white text-xs font-bold">1</span>
          </div>
          <p class="text-xs sm:text-sm text-white/90">Make sure the screenshot is clear and well-lit</p>
        </div>
        <div class="flex items-start space-x-2 sm:space-x-3">
          <div class="w-5 h-5 sm:w-6 sm:h-6 bg-dark-cyan/40 rounded-full flex items-center justify-center flex-shrink-0 mt-0.5">
            <span class="text-white text-xs font-bold">2</span>
          </div>
          <p class="text-xs sm:text-sm text-white/90">Include the main dashboard view with steps and calories visible</p>
        </div>
        <div class="flex items-start space-x-2 sm:space-x-3">
          <div class="w-5 h-5 sm:w-6 sm:h-6 bg-cyan/30 rounded-full flex items-center justify-center flex-shrink-0 mt-0.5">
            <span class="text-white text-xs font-bold">3</span>
          </div>
          <p class="text-xs sm:text-sm text-white/90">Upload regularly to track your progress. Securely integrated with Clienta app.</p>
        </div>
      </div>
    </div>
  </main>
</div>
